#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

const int N = 6;
int    code[N]  = {101, 102, 103, 104, 105, 106};
string item[N]  = {"Notebook", "Pen", "Pencil box", "Geometry box",
                   "Water bottle", "School bag"};
double price[N] = {45, 10, 120, 85, 150, 650};
int    stock[N] = {50, 100, 20, 15, 10, 5};
int    sold[N]  = {0, 0, 0, 0, 0, 0};

double todaySales = 0;
int    billCount  = 0;

void showMenu() {
    cout << "\n===== SHOP MENU =====\n";
    cout << "1. Show items\n2. Make a bill\n3. Restock an item\n";
    cout << "4. Daily report\n5. Exit\n";
    cout << "Choice: ";
}

void showItems() {
    cout << "\nCode  " << left << setw(14) << "Item" << right
         << setw(8) << "Price" << setw(8) << "Stock" << endl;
    for (int i = 0; i < N; i++)
        cout << code[i] << "   " << left << setw(14) << item[i] << right
             << setw(8) << price[i] << setw(8) << stock[i] << endl;
}

int findItem(int c) {                 // returns index, or -1 if not found
    for (int i = 0; i < N; i++)
        if (code[i] == c)
            return i;
    return -1;
}

void makeBill() {
    int    lineItem[20], lineQty[20];
    int    lines = 0;
    double subtotal = 0;
    int    c, q;

    cout << "Enter item code and quantity (0 0 to finish):\n";
    cin >> c >> q;
    while (c != 0 && lines < 20) {
        int i = findItem(c);
        if (i == -1)
            cout << "  No item with code " << c << endl;
        else if (q <= 0)
            cout << "  Quantity must be positive" << endl;
        else if (q > stock[i])
            cout << "  Only " << stock[i] << " " << item[i] << " in stock" <<
endl;
        else {
            stock[i] -= q;
            sold[i]  += q;
            lineItem[lines] = i;
            lineQty[lines]  = q;
            lines++;
            subtotal += price[i] * q;
        }
        cin >> c >> q;
    }
    if (lines == 0) {
        cout << "No items billed.\n";
        return;
    }

    double discount = (subtotal >= 1000) ? subtotal * 5 / 100 : 0;
    double net = subtotal - discount;
    billCount++;
    todaySales += net;

    cout << fixed << setprecision(2);
    cout << "\n------------- BILL No. " << billCount << " -------------\n";
    cout << left << setw(14) << "Item" << right << setw(5) << "Qty"
         << setw(9) << "Rate" << setw(11) << "Amount" << endl;
    for (int k = 0; k < lines; k++) {
        int i = lineItem[k];
        cout << left << setw(14) << item[i] << right << setw(5) << lineQty[k]
             << setw(9) << price[i] << setw(11) << price[i] * lineQty[k] <<
endl;
    }
    cout << "----------------------------------------\n";
    cout << left << setw(28) << "Subtotal" << right << setw(11) << subtotal
<< endl;
    cout << left << setw(28) << "Discount (5% on 1000+)" << right << setw(11)
<< discount << endl;
    cout << left << setw(28) << "Net amount" << right << setw(11) << net <<
endl;
    cout << "----------------------------------------\n";
    cout.unsetf(ios::fixed);
    cout << setprecision(6);
}

void restock() {
    int c, q;
    cout << "Item code and quantity to add: ";
    cin >> c >> q;
    int i = findItem(c);
    if (i == -1 || q <= 0) {
        cout << "Invalid code or quantity\n";
        return;
    }
    stock[i] += q;
    cout << item[i] << " stock is now " << stock[i] << endl;
}

void dailyReport() {
    cout << "\n------ DAILY REPORT ------\n";
    for (int i = 0; i < N; i++)
        if (sold[i] > 0)
            cout << left << setw(14) << item[i] << right << " sold: " <<
sold[i] << endl;
    cout << "Bills made   : " << billCount << endl;
    cout << fixed << setprecision(2);
    cout << "Total sales  : Rs " << todaySales << endl;
    cout.unsetf(ios::fixed);
    cout << setprecision(6);
    cout << "Low stock (below 5):";
    bool any = false;
    for (int i = 0; i < N; i++)
        if (stock[i] < 5) {
            cout << " " << item[i] << "(" << stock[i] << ")";
            any = true;
        }
    if (!any) cout << " none";
    cout << endl;
}

int main() {
    int choice;
    cout << "Welcome to Vidya Stationery, Patna\n";
    do {
        showMenu();
        cin >> choice;
        switch (choice) {
            case 1: showItems();   break;
            case 2: makeBill();    break;
            case 3: restock();     break;
            case 4: dailyReport(); break;
            case 5: cout << "Shop closed. Thank you!\n"; break;
            default: cout << "Invalid choice\n";
        }
    } while (choice != 5);
    return 0;
}
